void uiAimPriority(lemming::aim::Settings& cfg){float s=g_uiScale;const char* names[]={"FOV","Distance","Low HP"};auto a=ImGui::GetCursorScreenPos();float width=(ImGui::GetContentRegionAvail().x-12*s)/3;for(int i=0;i<3;++i){ImGui::SetCursorScreenPos(ImVec2(a.x+i*(width+6*s),a.y));ImGui::PushID(i);if(uiChoiceButton("priority",names[i],cfg.priority==i,ImVec2(width,44*s)))cfg.priority=i;ImGui::PopID();}ImGui::SetCursorScreenPos(ImVec2(a.x,a.y+52*s));}
