 bool silent=g_subsection==1||(g_subsection==2&&g_aimEditMode==1);auto& cfg=silent?g_aimUi.silent:g_aimUi.normal;int state=!cfg.enabled?0:((g_aimUi.pauseInMenu&&lemming::aim::g_menuOpen.load())?2:(silent?g_silentState.load():g_normalState.load()));uiText(d,ImVec2(x+410*s,y+602*s),g_subsection==3?"Center + 6 bounded points per hitbox; scale uses the smallest extent.":stateText(state),uiColor(ImVec4(.52f,.60f,.73f,1)),15*s,g_uiSmallFont);publish(g_aimUi);
